use std :: io ; # [doc = " Trait for synchronized output writing."] # [doc = " Provides two output channels (primary and error) with flush support."] # [doc = " Implementors must ensure thread-safe writes."] pub trait ConsoleWriter : Send + Sync { # [doc = " Writes bytes to primary output."] fn write (& self , buf : & [u8]) -> io :: Result < usize > ; # [doc = " Writes bytes to error output."] fn write_err (& self , buf : & [u8]) -> io :: Result < usize > ; # [doc = " Flushes primary output."] fn flush (& self) -> io :: Result < () > ; # [doc = " Flushes error output."] fn flush_err (& self) -> io :: Result < () > ; }